{
  "schema_version": 1,
  "name": "graded_belief_allocation",
  "summary": "Graded 10-point belief allocation across 3-4 objects and 2-3 features on informative and prior trials, testing whether theories fitted to forced choice generalize to full referent probability distributions.",
  "charter": {
    "question": "When listeners allocate graded credence (10 points) across candidate referents on informative and uninformative trials, do their full belief distributions follow recursive pragmatic inference with shared perceptual priors, depth-3 graded lexical precision, competitor-confusion avoidance, or a non-Bayesian singleton oddity heuristic?"
  },
  "instructions": {
    "welcome": "Welcome! In this short study, you will play a communication game where a speaker describes one of the objects on the screen.",
    "task": "On each turn, you and the speaker see the same row of objects. The speaker has one target object in mind and says a single word that names a part on their target object. Your job is to split 10 points across the objects (using whole numbers that add up to 10) to show how likely each object is to be the speaker's target. Give more points to objects you think are more likely, and 0 points to objects that do not have the named part. On some turns, the speaker's word was cut off; on those turns, split your 10 points across the objects based on which object you think the speaker is most likely to talk about.",
    "comprehension_checks": [
      {
        "question": "How many total points must you split across the objects on each turn?",
        "options": [
          "10 points in total across the objects",
          "10 points for every single object",
          "1 point in total"
        ],
        "correct": 0
      },

