input.content:
{
  "schema_version": 1,
  "name": "structural_complexity_choice",
  "summary": "Forced-choice referent selection across 2-5 objects and 2-4 features with prior queries and synonyms, testing depth-1 vs depth-2 recursion, multi-cue structural priors, and feature parsimony.",
  "charter": {
    "question": "When listeners select a single referent across scenes varying in object count (2-5), feature dimensionality (2-4), synonym availability, and informative vs. prior trials, are their choices governed by singleton-only bounded-depth RSA, a rich multi-cue structural prior (feature complexity and Hamming distinctiveness), a feature-parsimony penalty, or depth-2 recursive inference?"
  },
  "instructions": {
    "welcome": "Welcome! In this short study, you will play a communication game where a speaker describes one of the objects on the screen.",
    "task": "On each turn, you and the speaker see the same row of objects. The speaker has one target object in mind and says a single word that names a part on their target object. Your job is to click on the object you think is the speaker's target. An object must have the named part to be the target when the speaker says a word. On some turns, the speaker's word was cut off; on those turns, click on the object you think the speaker is most likely to talk about.",
    "comprehension_checks": [
      {
        "question": "What is your job when the speaker says a word?",
        "options": [
          "Click on the single object you think is the speaker's target",
          "Click on every object on the screen",
          "Click on an object that does not have the named part"
        ],
        "correct": 0
      },
      {
        "question": "Can an object that does not have the part named by the speaker be the target on that turn?",
        "options": [
          "No, the target object always has the part named by the speaker",
          "Yes, the speaker says random words that do not match the target",
          "Only if it is on the left side of the screen"
        ],
        "correct": 0
